                                 'thông reo vi vu, ghé thăm thác Pa Sỹ cuồn cuộn bọt trắng xóa đổ '
                                 'xuống từ vách đá chênh vênh, hay tĩnh tâm viếng thăm tượng Đức Mẹ '
