                                 'mét. Hành trình đi cano thúng vượt qua làn nước xanh biếc sẽ đưa du '
                                 'khách tiếp cận những bãi đá nhấp nhô tuyệt đẹp bao quanh chân tháp, '
                                 'lý tưởng cho những góc máy hoang dại. Leo 183 bậc thang xoắn ốc bằng '
                                 'thép bên trong ngọn tháp bằng đá granite để lên tới đỉnh lồng đèn, '
                                 'bạn sẽ được tưởng thưởng bằng toàn cảnh biển Đông hùng vĩ lộng gió. '
                                 'Sự hòa quyện giữa kiến trúc Pháp cổ kính vững chãi và thiên nhiên '
                                 'biển đảo nguyên sơ mang lại một chuyến đi khám phá thấm đẫm chất thơ '
