                                 'xuyên qua những ô cửa kính màu chiếu lên các hàng cột gỗ đen bóng '
                                 'tạo nên một không gian vô cùng thiêng liêng, huyền bí. Nằm yên bình '
                                 'giữa lòng thành phố, đây là biểu tượng văn hóa lịch sử, thu hút du '
                                 'khách đến chiêm ngưỡng và tìm kiếm những bức ảnh mang vẻ đẹp hoài '
                                 'cổ.',
