                                 'điểm xuyết những cành liễu rủ. Khắp nơi trong chùa là những khu vườn '
                                 'tiểu cảnh bonsai được chăm chút tỉ mỉ, tượng Phật trang nghiêm và '
                                 'những bức hoành phi gỗ chạm trổ cầu kỳ. Không chỉ là chốn hành hương '
