                                 'làng bừng sáng bởi một thảm màu sắc rực rỡ kéo dài tít tắp, tạo nên '
                                 'một lễ hội thị giác lộng lẫy vô song. Du khách sẽ bắt gặp hình ảnh '
                                 'những người nông dân chèo xuồng len lỏi giữa các luống hoa để chăm '
